const generated: MidtermQuestion[] = [];
let nextId = 20001;
function add(question: Omit<MidtermQuestion, 'id'>) {
  const id = nextId++;
  const offset = id % (question.options?.length ?? 1);
  const options = question.options ? [...question.options.slice(offset), ...question.options.slice(0, offset)] : undefined;
  const answer = question.answer?.map((index) => (index - offset + question.options!.length) % question.options!.length).sort((a,b)=>a-b);
  generated.push({id,...question,options,answer});
}

for (const item of cases) {
  const day = `${item.level} · ${item.day}`;
  const caseMaterial = `${item.title}\n${item.artifact}`;
  const shared = {day,topic:`${item.level} · ${item.topic}`,caseMaterial,workSample:true};
  add({...shared,kind:'single',prompt:`[${item.title}] Vấn đề nào cần được điều tra trước khi chấp nhận artifact?`,options:[item.issue,'Artifact chắc chắn hợp lệ vì job đã chạy xong','Chỉ cần đổi tên artifact rồi chạy lại','Không cần xem evidence nếu output nhìn có vẻ hợp lý'],answer:[0],explanation:item.repair});
  add({...shared,kind:'multiple',prompt:`[${item.title}] Chọn hai bằng chứng trực tiếp nhất để xác minh nguyên nhân và phạm vi ảnh hưởng.`,options:[...item.evidence,...item.distractors],answer:[0,1],explanation:`Evidence: ${item.evidence.join('; ')}.`});
  add({...shared,kind:'boolean',prompt:`[${item.title}] Đúng hay sai? ${item.misconception}`,options:['Đúng','Sai'],answer:[1],explanation:item.repair});
  add({...shared,kind:'written',prompt:`[${item.title}] Viết review note: chẩn đoán lỗi, nêu phạm vi, bước khắc phục và evidence cần có trước khi release/đóng incident.`,explanation:'Tự đối chiếu theo rubric. Bài làm tốt chỉ rõ artifact, evidence, rủi ro và cách xác nhận sau sửa.',rubric:[...item.rubric]});
}

