function shuffle<T>(items:T[], random:()=>number):T[] {
  const result=[...items];
  for(let i=result.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}
  return result;
}
export function pickAiThucChienExam(random=Math.random, excludedIds:number[]=[]):MidtermQuestion[] {
  const quotas:Record<MidtermQuestion['kind'],number>={single:30,multiple:8,boolean:6,written:6};
  const workQuotas:Partial<Record<MidtermQuestion['kind'],number>>={single:5,multiple:2,written:1};
  const excluded=new Set(excludedIds);
  const selected=(['single','multiple','boolean','written'] as const).flatMap(kind=>{
    const all=aiThucChienQuestions.filter(q=>q.kind===kind);
    const unseen=all.filter(q=>!excluded.has(q.id));
    const pool=unseen.length>=quotas[kind]?unseen:all;
    const practical=shuffle(pool.filter(q=>q.workSample),random).slice(0,workQuotas[kind]??0);
    const regular=shuffle(pool.filter(q=>!practical.includes(q)),random).slice(0,quotas[kind]-practical.length);
    return [...practical,...regular];
  });
  return shuffle(selected,random);
}
